const { execSync } = require('child_process');
const prj = process.env.HOME + '/Library/Mobile Documents/com~apple~CloudDocs/Kit-Piloto-Automatico-V30-DISTRIB';
const base = `${prj}/18_AUTOMATION_STACK/impar-facebook-marketplace-posting`;
const ts = new Date().toISOString();
const check = (cmd) => { try { return execSync(cmd, {timeout:5000}).toString().trim(); } catch(e) { return 'error'; } };
const fila = check(`wc -l < "${base}/../../../05_WORKSPACE/clientes/impar/fila-postagens.csv" 2>/dev/null || wc -l < "${prj}/KPA30-Marketplace/fila-postagens.csv" 2>/dev/null || echo 'n/a'`);
const scripts = ['crosspost_groups_v2.py','publish_daily_from_fila.py','publish_marketplace_playwright.py'].map(s => ({ name: s, exists: check(`test -f "${base}/${s}" && echo yes || echo no`) === 'yes' }));
const lastLog = check(`ls -t "${base}/logs/" 2>/dev/null | head -1 || echo 'none'`);
return [{ json: { status: 'monitored', ai_used: false, timestamp: ts, mode: 'READ_ONLY', publish_disabled: true, queue_lines: fila, scripts, last_log: lastLog } }];
